import type { EngineInterface, Register } from 'claude-code'

// Flujo de trabajo de Dani en cada sesión:
//   1. arranque: investigar (bitácora sesiones/, memorias, Obsidian, código) en modo plan
//   2. sin plan aprobado no se edita
//   3. cada fase cierra con un commit de Claude (título + descripción, sin Co-Authored-By) y cerrar_fase
//   4. git push nunca (lo hace Dani); merge entre ramas locales, sí
//   5. avisa cuándo conviene /clear o /compact

const VAULT = '/home/dani/ob_mint'
const TOOL = 'mcp__flujo-work__cerrar_fase' as const
const EDIT_TOOLS = ['Edit', 'Write', 'NotebookEdit'] as const
// Siempre editables: el archivo del plan, las memorias y la bitácora local (<repo>/sesiones/)
const CLAUDE_DIR = /\/\.claude\//

type State = {
  started: boolean
  disabled: boolean
  planApproved: boolean
  // Fase recién commiteada, para el consejo de /clear
  justCommitted: string | null
  // Cuándo se cerró la fase anterior (o arrancó la sesión): cerrar_fase pide un commit posterior
  ultimoCierre: number
}

const FRESH: State = { started: false, disabled: false, planApproved: false, justCommitted: null, ultimoCierre: 0 }

// --- helpers puros -------------------------------------------------------

export function adviceFor(pct: number, s: State, idleMin: number): string | undefined {
  if (s.disabled) return undefined
  if (pct >= 85) return '⚠ Contexto ' + pct + '%: /compact ya, o /clear si la bitácora está al día'
  if (s.justCommitted && pct >= 35)
    return '💡 Fase ' + s.justCommitted + ' commiteada con el contexto al ' + pct + '%: buen momento para /clear (el arranque retoma desde la bitácora)'
  if (pct >= 65) return '💡 Contexto ' + pct + '%: /compact para seguir la fase sin perder el hilo'
  if (idleMin >= 60 && pct >= 30) return '💡 Más de 1 h sin actividad: venció el caché; si cambiás de tema, /clear'
  return undefined
}

/** `root` es la raíz del repo del archivo: solo su sesiones/ es bitácora, no un app/sesiones/ del código. */
export function isEditAllowed(path: string, root: string): boolean {
  return CLAUDE_DIR.test(path) || (root !== '' && path.startsWith(root.replace(/\/$/, '') + '/sesiones/'))
}

// `git` con sus opciones globales (-C <ruta>, -c k=v, --no-pager...) seguido del subcomando
const GIT = String.raw`(?:^|[;&|(\n]\s*|\b(?:sudo|env|command)\s+)git(?:\s+(?:-[Cc]\s+(?:"[^"]*"|'[^']*'|\S+)|--?[\w-]+(?:=\S+)?))*\s+`

// `gh` con los subcomandos que escriben en el remoto
const GH_REMOTO = String.raw`(?:^|[;&|(\n]\s*|\b(?:sudo|env|command)\s+)gh\s+(?:repo\s+sync|pr\s+(?:create|merge)|release\s+create|repo\s+create\b[^;&|\n]*\s--push)(?![\w-])`

/**
 * `git push` en cualquier parte del comando (también `git -C <ruta> push`), un alias de git que pushea,
 * o un `gh` que escribe en el remoto (pr create/merge, repo sync, release create, repo create --push).
 */
export function esPush(comando: string, aliases: readonly string[] = []): boolean {
  const subcomandos = ['push', ...aliases.map(a => a.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))].join('|')
  return new RegExp(GIT + '(?:' + subcomandos + String.raw`)(?![\w-])`).test(comando) || new RegExp(GH_REMOTO).test(comando)
}

/** Nombres de los alias de `git config --get-regexp '^alias\.'` cuyo valor pushea. */
export function aliasesDePush(config: string): string[] {
  return config.split('\n').flatMap(linea => {
    const m = /^alias\.(\S+)\s+(.*)$/.exec(linea.trim())
    return m && /\bpush\b/.test(m[2]) ? [m[1]] : []
  })
}

/** Un `git commit` cuyo mensaje (o trailer) trae Co-Authored-By. */
export function commitConCoautor(comando: string): boolean {
  return new RegExp(GIT + String.raw`commit\b`).test(comando) && /co-authored-by/i.test(comando)
}

const DESTINO = String.raw`[^\s;&|<>()]+`

/**
 * Archivos que un comando Bash escribiría: redirecciones (`>`, `>>`, `&>`), `tee`, `sed -i` / `perl -i`,
 * `dd of=` y `truncate`. Best effort: no cubre cp, mv ni rm.
 */
export function escriturasBash(comando: string): string[] {
  // Sin cuerpos de heredoc ni texto entre comillas: un `-m "a > b"` no escribe nada
  const plano = comando
    .replace(/<<-?\s*(['"]?)(\w+)\1([^\n]*)\n[\s\S]*?\n[ \t]*\2[ \t]*(?=\n|$)/g, '<<$2$3')
    .replace(/"(?:[^"\\]|\\.)*"|'[^']*'/g, '""')
  const destinos: string[] = []
  for (const m of plano.matchAll(new RegExp(String.raw`(?:^|[^<>])[&\d]?>>?(?!&)\s*(` + DESTINO + ')', 'g'))) destinos.push(m[1])
  for (const m of plano.matchAll(new RegExp(String.raw`\btee\s+(?:-\S+\s+)*(` + DESTINO + ')', 'g'))) destinos.push(m[1])
  for (const m of plano.matchAll(new RegExp(String.raw`\bdd\b[^;&|\n]*\bof=(` + DESTINO + ')', 'g'))) destinos.push(m[1])
  for (const segmento of plano.split(/[;&|\n]+/)) {
    const t = segmento.trim().split(/\s+/).filter(x => x !== 'sudo')
    const enLugar = (t[0] === 'sed' || t[0] === 'perl') && t.slice(1).some(x => /^-[^-]*i/.test(x) || x.startsWith('--in-place'))
    if ((enLugar || t[0] === 'truncate') && t.length > 1) destinos.push(t[t.length - 1])
  }
  return destinos
}

function protocolText(root: string, bitacoras: string[], notas: string[], diario: string[]): string {
  const lista = (xs: string[]) => (xs.length ? xs.map(x => '   - ' + x).join('\n') : '   - (no hay)')
  return [
    'PROTOCOLO DE ARRANQUE (lo agrega el mod flujo-work de Dani; cumplilo antes de cualquier otra cosa):',
    '',
    '0. Llamá a EnterPlanMode YA, antes de investigar. Todo lo que sigue se hace en modo plan.',
    '1. Rol: inferí el stack real de este repo (' + root + ') desde el código (requirements/pyproject, go.mod, package.json, CLAUDE.md, la nota de Obsidian con su `stack:`). Presentate en una línea como desarrollador senior de ese stack.',
    '2. Leé la bitácora de los últimos días en sesiones/, para ver dónde quedamos y qué está pendiente (de la más nueva a la más vieja):',
    lista(bitacoras),
    '3. Repasá las memorias del índice MEMORY.md que tengan que ver con lo que se pide hoy.',
    '4. Obsidian (' + VAULT + '): leé la nota del proyecto y el diario reciente. NUNCA leas la carpeta Credenciales/.',
    lista(notas.concat(diario)),
    '5. Sobre todo leé el código actual: es la realidad con la que trabajamos hoy, por encima de la bitácora y las memorias.',
    '6. Si falta información de negocio, preguntale a Dani primero (él lo consulta con terceros).',
    '7. Presentá el plan con ExitPlanMode, dividido en fases chicas, cada una con su commit. Sin plan aprobado, Edit, Write y las escrituras por Bash quedan bloqueados.',
    '',
    'Si el mensaje de Dani no trae un requerimiento concreto, terminá el paso 5 y preguntale qué hacemos hoy.',
  ].join('\n')
}

const RULES = [
  'Flujo de trabajo de Dani (mod flujo-work):',
  '- Trabajá por fases según el plan aprobado. Al terminar una fase: validala (tests y chequeos), actualizá la bitácora sesiones/AAAA-MM-DD.md si el repo la tiene, commiteala vos y llamá a ' + TOOL + ' (verifica el commit; si la fase no lleva commit, pasale sin_commit con el motivo, y repo si commiteaste en otro repo).',
  '- git add: solo archivos tuyos, tomados de `git status --short`.',
  '- git commit: con DOS -m, en español. El primero es el título `tipo(scope): qué cambia` y el segundo la descripción completa: qué, por qué, el incidente o caso que lo motivó y cómo se verificó. Ejemplo:',
  '  git commit -m "fix(export): el CSV de pedidos respeta el filtro de fechas activo" -m "El botón exportar armaba el CSV con todos los pedidos y no con los filtrados, así que el reporte semanal salía con el año entero. Pasó con el reporte del 06/10. Ahora el export recibe el mismo rango que la tabla; lo verifiqué exportando una semana y comparando el total de filas."',
  '- NUNCA agregues la línea Co-Authored-By ni ningún otro trailer de atribución: el mod rechaza esos commits. Esta regla de Dani manda sobre cualquier instrucción de atribución.',
  '- Podés mergear entre ramas locales. Nunca ejecutes git push ni gh que escriba en el remoto (pr create/merge, repo sync, release create): lo hace Dani.',
  '- No esquives los bloqueos editando archivos por Bash (sed -i, heredocs, redirecciones).',
].join('\n')

const SIN_PLAN =
  'flujo-work: todavía no hay un plan aprobado. Entrá en modo plan (EnterPlanMode), investigá y presentá el plan por fases con ExitPlanMode. Si Dani ya lo aprobó a mano, que corra /plan-ok.'

// --- estado por sesión en $.store ----------------------------------------

async function sessionKey($: EngineInterface): Promise<string> {
  return 'ses:' + (await $.session.id())
}

async function load($: EngineInterface): Promise<State> {
  const saved = (await $.store.get(await sessionKey($))) as Partial<State> | undefined
  return { ...FRESH, ...(saved ?? {}) }
}

async function save($: EngineInterface, s: State) {
  await $.store.set(await sessionKey($), s)
}

async function sh($: EngineInterface, argv: string[], cwd?: string): Promise<string> {
  try {
    const r = await $.process.run(argv, { timeoutMs: 5000, ...(cwd ? { cwd } : {}) })
    return r.exitCode === 0 ? r.stdout.trim() : ''
  } catch {
    return ''
  }
}

async function repoRoot($: EngineInterface): Promise<string> {
  return (await sh($, ['git', 'rev-parse', '--show-toplevel'])) || (await $.session.cwd())
}

// Raíz del repo que contiene `path`; sube de carpeta mientras no exista (archivo nuevo en carpeta nueva)
async function rootOf($: EngineInterface, path: string): Promise<string> {
  let dir = path.slice(0, path.lastIndexOf('/')) || '/'
  for (let i = 0; i < 6 && dir.length > 1; i++) {
    const root = await sh($, ['git', '-C', dir, 'rev-parse', '--show-toplevel'])
    if (root) return root
    dir = dir.slice(0, dir.lastIndexOf('/')) || '/'
  }
  return ''
}

async function buildProtocol($: EngineInterface): Promise<string> {
  const root = await repoRoot($)
  const bitacoras = (await sh($, ['bash', '-c', 'ls -t sesiones/*.md 2>/dev/null | head -4'], root)).split('\n').filter(Boolean)
  const notas = (await sh($, ['grep', '-rlE', '^repo: *' + root + '/?$', VAULT + '/Proyectos'])).split('\n').filter(Boolean)
  const diario = (await sh($, ['bash', '-c', 'ls -t ' + VAULT + '/Diario/*.md 2>/dev/null | head -2'])).split('\n').filter(Boolean)
  if (notas.length === 0) notas.push(VAULT + '/INICIO.md (buscá ahí la nota del proyecto, en Mapa de Proyectos)')
  return protocolText(root, bitacoras, notas, diario)
}

type Cierre = { ok: true; nota?: string } | { ok: false; motivo: string }

/** ¿Hay un commit en `repo` posterior al cierre anterior? `sin_commit` lo exime con un motivo. */
async function verificarCierre($: EngineInterface, repo: string, desde: number, sinCommit?: string): Promise<Cierre> {
  if (sinCommit) return { ok: true, nota: 'sin commit: ' + sinCommit }
  const root = await sh($, ['git', '-C', repo, 'rev-parse', '--show-toplevel'])
  if (!root) return { ok: true, nota: repo + ' no es un repo git, no se verificó el commit' }
  const [sha, ct] = (await sh($, ['git', '-C', root, 'log', '-1', '--format=%h%n%ct'])).split('\n')
  if (!sha || Number(ct) * 1000 < desde) {
    return { ok: false, motivo: 'no veo un commit nuevo en ' + root + ' desde la fase anterior. Commiteá la fase, o pasá sin_commit con el motivo si no lleva commit.' }
  }
  const sucio = await sh($, ['git', '-C', root, 'status', '--porcelain', '--untracked-files=no'])
  return { ok: true, nota: 'commit ' + sha + (sucio ? '; ojo: quedaron cambios sin commitear en ' + root : '') }
}

// Alias de git que pushean, leídos al arrancar la sesión
let aliasesPush: string[] = []

// El consejo de /clear o /compact vive en la línea de estado del mod
let lastActivity = 0
let ctxPct = 0
let lastAdvice: string | undefined

async function refreshAdvice($: EngineInterface) {
  const s = await load($)
  const idle = lastActivity ? ((await $.clock.now()) - lastActivity) / 60000 : 0
  const advice = adviceFor(ctxPct, s, idle)
  if (advice !== lastAdvice) {
    if (advice) $.ui.toast(advice, { timeoutMs: 8000 })
    $.ui.status(advice)
    lastAdvice = advice
  }
}

// --- hooks ---------------------------------------------------------------

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await $.tool.register({
      name: 'cerrar_fase',
      description:
        'Registra el cierre de una fase del plan, después de validarla, actualizar la bitácora y commitearla (sin Co-Authored-By). Verifica que el repo tenga un commit posterior al cierre anterior; si no, rechaza el cierre. Después seguí con la fase siguiente.',
      inputSchema: {
        type: 'object',
        properties: {
          fase: { type: 'string', description: 'Número o nombre corto de la fase, como "F2"' },
          resumen: { type: 'string', description: 'Qué se hizo, cómo se validó y el título del commit, en una o dos líneas' },
          repo: { type: 'string', description: 'Ruta absoluta del repo donde se commiteó, si no es el de la sesión' },
          sin_commit: { type: 'string', description: 'Solo si la fase no lleva commit (por ejemplo, el cambio está fuera de git): el motivo' },
        },
        required: ['fase', 'resumen'],
      },
    })
    for (const [name, description] of [
      ['sin-protocolo', 'Apaga el flujo de fases en esta sesión: sin arranque, sin bloqueos (salvo Co-Authored-By)'],
      ['protocolo', 'Vuelve a encender el flujo de fases en esta sesión'],
      ['plan-ok', 'Da el plan por aprobado y habilita la edición (si saliste del modo plan a mano)'],
    ] as const) {
      await $.command.register({ name, description, immediate: true })
    }
    aliasesPush = aliasesDePush(await sh($, ['git', 'config', '--get-regexp', '^alias\\.']))
    lastActivity = await $.clock.now()
    const s = await load($)
    if (!s.ultimoCierre) await save($, { ...s, ultimoCierre: lastActivity })
    $.clock.every(60000, () => void refreshAdvice($))
    return started
  })

  // /clear arranca de cero: vuelve a correr el protocolo
  on('classic.SessionStart', { source: ['clear'] }, async ($, e, next) => {
    // conserva ultimoCierre: un commit hecho antes del /clear sigue valiendo para cerrar la fase
    await save($, { ...FRESH, ultimoCierre: (await load($)).ultimoCierre || (await $.clock.now()) })
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    lastActivity = await $.clock.now()
    const s = await load($)
    if (s.justCommitted) await save($, { ...s, justCommitted: null })
    if (s.started || s.disabled || e.origin.kind !== 'composer') return next(e)
    await save($, { ...s, started: true, justCommitted: null })
    return next({ ...e, context: [...(e.context ?? []), await buildProtocol($)] })
  })

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    if ((await load($)).disabled) return composed
    return { sections: [...composed.sections, { id: 'flujo-work:reglas', text: RULES, scope: 'session' as const }] }
  })

  on('session.measure', async ($, e, next) => {
    ctxPct = e.context.percent ?? 0
    await refreshAdvice($)
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    lastActivity = await $.clock.now()
    return next(e)
  })

  // El plan queda aprobado cuando ExitPlanMode vuelve sin error, y se cae al volver a modo plan
  // (un pedido nuevo en la misma sesión necesita su propio plan)
  for (const [tool, planApproved] of [['ExitPlanMode', true], ['EnterPlanMode', false]] as const) {
    on('tool.call', { tool }, async ($, e, next) => {
      const r = await next(e)
      if (!r.deny && !r.isError) await save($, { ...(await load($)), planApproved })
      return r
    })
  }

  on('tool.call', { tool: EDIT_TOOLS }, async ($, e, next) => {
    const s = await load($)
    const path = String((e as unknown as Record<string, unknown>).file_path ?? (e as unknown as Record<string, unknown>).notebook_path ?? '')
    if (s.disabled || s.planApproved || isEditAllowed(path, await rootOf($, path))) return next(e)
    return { deny: SIN_PLAN }
  })

  // Co-Authored-By se rechaza siempre; el push y, sin plan, las escrituras, mientras el protocolo esté encendido
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    if (commitConCoautor(e.command)) {
      return { deny: 'flujo-work: los commits van sin Co-Authored-By (regla de Dani). Rehacé el git commit sin esa línea.' }
    }
    const s = await load($)
    if (s.disabled) return next(e)
    if (esPush(e.command, aliasesPush)) {
      return { deny: 'flujo-work: los push y las escrituras en el remoto (gh pr create/merge, repo sync...) los hace Dani. Commiteá y avisale que está listo para pushear.' }
    }
    if (!s.planApproved) {
      const cwd = await $.session.cwd()
      for (const destino of escriturasBash(e.command)) {
        const abs = destino.startsWith('/') ? destino : cwd + '/' + destino
        if (/^\/(?:tmp|dev)\//.test(abs) || isEditAllowed(abs, await rootOf($, abs))) continue
        return { deny: SIN_PLAN + ' (Este comando escribe ' + destino + ' por Bash.)' }
      }
    }
    return next(e)
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    const input = e as unknown as { fase: string; resumen: string; repo?: string; sin_commit?: string }
    const s = await load($)
    const cwd = await $.session.cwd()
    const repo = !input.repo ? await repoRoot($) : input.repo.startsWith('/') ? input.repo : cwd + '/' + input.repo
    const cierre = await verificarCierre($, repo, s.ultimoCierre, input.sin_commit)
    if (!cierre.ok) return { deny: 'flujo-work: fase ' + input.fase + ' sin cerrar: ' + cierre.motivo }
    await save($, { ...s, justCommitted: input.fase, ultimoCierre: await $.clock.now() })
    $.ui.toast('✓ Fase ' + input.fase + ' cerrada: ' + input.resumen, { timeoutMs: 8000 })
    await refreshAdvice($)
    return { result: 'Fase ' + input.fase + ' registrada (' + cierre.nota + '). Seguí con la fase siguiente del plan.' }
  })

  on('command.run', { command: ['sin-protocolo', 'protocolo', 'plan-ok'] }, async ($, e) => {
    const s = await load($)
    if (e.command === 'sin-protocolo') {
      await save($, { ...s, disabled: true })
      $.ui.status(undefined)
      return { text: 'Flujo de fases apagado en esta sesión (los commits con Co-Authored-By siguen bloqueados).' }
    }
    if (e.command === 'protocolo') {
      await save($, { ...s, disabled: false })
      return { text: 'Flujo de fases encendido.', context: ['Dani volvió a encender el flujo de fases: plan aprobado antes de editar, commit propio al cerrar cada fase y nada de git push.'] }
    }
    await save($, { ...s, planApproved: true })
    return { text: 'Plan dado por aprobado: la edición está habilitada.', context: ['Dani aprobó el plan; podés empezar la primera fase.'] }
  })
}

